import { canCreateObjects, generatedLayerCreateMessage } from './geo_layer_rules.js';

async function getProjectInfo(project) {
  try {
    // let url = `http://127.0.0.1:5000/geo/project_info?project=${project}`;
    let url = `/geo/project_info?project=${encodeURIComponent(project)}`;
    const geoResponse = await fetch(url, {
      method: 'POST',
    });
    const result = await geoResponse.json();
    if (!geoResponse.ok) throw new Error(result.err_info || `Ошибка сервера: ${geoResponse.status}`);
    return result;
  } catch (err) {
    console.log('Ошибка получения данных о проекте', err);
    throw err;
  }
}

async function getDataLayer(project, layer_name) {
  try {
    // let url = `http://127.0.0.1:5000/geo/get_data?project=${project}&layer_name=${layer_name}`;
    let url = `/geo/get_data?project=${encodeURIComponent(project)}&layer_name=${encodeURIComponent(layer_name)}`;
    const geoResponse = await fetch(url, {
      method: 'POST'
    });
    const result = await geoResponse.json();
    if (!geoResponse.ok) throw new Error(result.err_info || `Ошибка сервера: ${geoResponse.status}`);
    return result;
  } catch (err) {
    console.log('Ошибка получения данных слоя', err);
    throw err;
  }
}

async function postDataLayer(json_data) {
  try {
    if (['createDM', 'createSM'].includes(json_data.action_type)
        && !canCreateObjects(json_data.layer)) {
      throw new Error(generatedLayerCreateMessage);
    }
    // let url = `http://127.0.0.1:5000/geo/post_data`;
    let url = `/geo/post_data`;
    // console.log(json_data);
    const geoResponse = await fetch(url, {
      method: 'POST',
      headers: {
        Accept: 'application/json',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(json_data)
    });
    const result = await geoResponse.json();
    if (!geoResponse.ok) {
      throw new Error(result.err_info || `Ошибка сервера: ${geoResponse.status}`);
    }
    // console.log(result);
    return result;
  } catch (err) {
    console.log('Ошибка отправки данных на сервер', err);
    throw err;
  }
}

export { getProjectInfo, getDataLayer, postDataLayer };
