const DEFAULT_LAYER_COLOR = '#3399FF';

function normalizeLayerColor(color) {
  return /^#[0-9A-Fa-f]{6}$/.test(color || '') ? color : DEFAULT_LAYER_COLOR;
}

function colorWithAlpha(color, alpha) {
  const normalized = normalizeLayerColor(color);
  const red = parseInt(normalized.slice(1, 3), 16);
  const green = parseInt(normalized.slice(3, 5), 16);
  const blue = parseInt(normalized.slice(5, 7), 16);
  return `rgba(${red}, ${green}, ${blue}, ${alpha})`;
}

// Создаёт единый стиль точки, линии или полигона из цвета слоя.
function createLayerStyle(color) {
  const normalized = normalizeLayerColor(color);
  return new Style({
    fill: new Fill({
      color: colorWithAlpha(normalized, 0.32),
    }),
    stroke: new Stroke({
      color: colorWithAlpha(normalized, 0.9),
      width: 2,
    }),
    image: new CircleStyle({
      radius: 4.4,
      stroke: new Stroke({
        color: 'rgba(255, 255, 255, 0.9)',
        width: 2,
      }),
      fill: new Fill({
        color: normalized,
      }),
    }),
  });
}

