let prjLayersInfo = null;
const isTechnicalField = (fieldName) => ['wkt', 'geometry'].includes(
  String(fieldName).trim().toLowerCase()
);

function removeTechnicalFieldsFromConfig(layersInfo) {
  for (const layerInfo of Object.values(layersInfo || {})) {
    for (const fieldName of Object.keys(layerInfo.fields || {})) {
      if (isTechnicalField(fieldName)) {
        delete layerInfo.fields[fieldName];
      }
    }
  }
  return layersInfo;
}

const project = decodeURIComponent(window.location.pathname.split('/geoapp/')[1]);

