async function loadLayers() {
  const projectExtent = createEmpty();
  const loads = [];
  for (let l in prjLayersInfo) {
    loads.push(getDataLayer(project, l).then(result => {
      let layerSource = null;
      if (result?.data?.type === 'FeatureCollection') {
        try {
          let features = new GeoJSON().readFeatures(result.data);
          layerSource = new VectorSource({
            features: features,
          });
        } catch (err) {
          layerSource = new VectorSource();
          console.log(`Ошибка получения данных слоя ${l}`, err);
        }
      } else {
        layerSource = new VectorSource();
      }
      const layerColor = prjLayersInfo[l]['color'];
      const layerStyle = createLayerStyle(layerColor);
      let vectorLayer = new VectorLayer({
        properties: { 'layer_name': l, 'layer_color': layerColor },
        source: layerSource,
        style: layerStyle,
        zIndex: prjLayersInfo[l]['zIndex'],
      });
      map.addLayer(vectorLayer);
      if (layerSource.getFeatures().length > 0) {
        extend(projectExtent, layerSource.getExtent());
      }
      // Для слоя добавляем кнопки, а слой добавляем на карту
      const div = document.createElement('div');
      div.innerHTML = `
                    <input id="setVisibleLayerBtn-${escapeHtml(l)}" type="checkbox" checked="true"/>
                    <span class="layer_color_marker" style="background-color: ${layerColor};" title="Цвет слоя ${layerColor}"></span>
                    <label class="layer_name_label">${escapeHtml(prjLayersInfo[l]['layer_name'])}</label>
                    <button id="showBtn-${escapeHtml(l)}"><img src="/static/img/fit.png" alt="Центрировать" title="Центрировать" width="14" height="14"></button>
                    <button id="tableBtn-${escapeHtml(l)}"><img src="/static/img/table.png" alt="Открыть таблицу" title="Открыть таблицу" width="16" height="16"></button>
                    <button id="createBtn-${escapeHtml(l)}"><img src="/static/img/create.png" alt="Создать новый объект" title="Создать новый объект" width="16" height="16"></button>
                    `
      layersControl.appendChild(div);
      div.classList.add("lc_elem");
      let setVisibleLayerBtn = document.getElementById(`setVisibleLayerBtn-${l}`);
      let fitLayerBtn = document.getElementById(`showBtn-${l}`);
      let tableBtn = document.getElementById(`tableBtn-${l}`);
      let createBtn = document.getElementById(`createBtn-${l}`);
      createBtn.disabled = !canCreateObjects(l);
      createBtn.title = createBtn.disabled ? generatedLayerCreateMessage : 'Создать новый объект';
      createBtn.querySelector('img').title = createBtn.title;
      setVisibleLayerBtn.onclick = () => vectorLayer.setVisible(setVisibleLayerBtn.checked);
      fitLayerBtn.onclick = () => {
        if (vectorLayer.getSource().getFeatures().length === 0) return;
        const layerGeometry = vectorLayer.getSource()?.getExtent();
        view.fit(layerGeometry, { padding: [30, 50, 30, 50], duration: 300 });
      }
      tableBtn.onclick = () => {
        showTable(l, vectorLayer);
        // console.log('table on');
      }
      createBtn.onclick = () => {
        if (createMode == true) {
          console.log('Режим создания объекта уже включен, завершите или отмените действие');
          return;
        } else {
          createObject(l, vectorLayer);
        }
      }
    }).catch(showGeoError));
  }
  await Promise.all(loads);
  if (!isEmpty(projectExtent)) {
    map.updateSize();
    view.fit(projectExtent, { padding: [30, 50, 30, 50], duration: 0, maxZoom: 16 });
  }
}

