function hideObjectCandidates() {
  objectCandidates.style.display = 'none';
  objectCandidatesList.replaceChildren();
}

function getObjectCandidateLabel(feature, layer, position) {
  const layerName = layer.get('layer_name');
  const layerTitle = prjLayersInfo[layerName]?.layer_name || layerName || 'Слой';
  const objectName = feature.get('name');
  const objectId = feature.get('id');
  const nameText = objectName === undefined || objectName === null
    ? ''
    : String(objectName).trim();
  const idText = objectId === undefined || objectId === null
    ? ''
    : String(objectId).trim();

  if (idText && nameText) {
    return `${layerTitle}: id-${idText}, "${nameText}".`;
  }
  if (idText) {
    return `${layerTitle}: id-${idText}.`;
  }
  if (nameText) {
    return `${layerTitle}: "${nameText}".`;
  }
  return `${layerTitle}: объект ${position + 1}.`;
}

function selectObjectCandidate(feature, layer) {
  if (!select) {
    return;
  }
  const selectedFeatures = select.getFeatures();
  selectedFeatures.clear();
  selectedFeatures.push(feature);
  hideObjectCandidates();

  const geometry = feature.getGeometry();
  makeFields(feature, geometry.getCoordinates(), geometry.getType(), layer);
}

function showObjectCandidates(candidates) {
  objectCandidatesList.replaceChildren();
  objInfo.style.display = 'none';
  objInfoDiv.innerHTML = '';

  candidates.forEach(({ feature, layer }, position) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'object_candidate_button';
    button.title = getObjectCandidateLabel(feature, layer, position);

    const marker = document.createElement('span');
    marker.className = 'object_candidate_marker';
    marker.style.backgroundColor = layer.get('layer_color') || '#3399FF';

    const text = document.createElement('span');
    text.className = 'object_candidate_text';
    text.textContent = button.title;

    button.append(marker, text);
    button.onclick = () => selectObjectCandidate(feature, layer);
    objectCandidatesList.appendChild(button);
  });

  objectCandidates.style.display = 'block';
}

closeObjectCandidatesBtn.onclick = function () {
  hideObjectCandidates();
  if (select) {
    select.getFeatures().clear();
  }
};

