const deleteMdfBtn = document.getElementById('delete_modify');
const snapMdfBtn = document.getElementById('modify_snap_mode');

function startSelect() {
  if (select) map.removeInteraction(select);
  clearSnap();
  modify = null;
  select = new Select({
    style: selected,
    wrapX: false,
    layers: function (layer) {
      return Boolean(layer.get('layer_name'));
    },
  });
  map.addInteraction(select);
}

map.on('singleclick', function (event) {
  if (createMode || modify !== null || drawMeasure !== null || !select) {
    return;
  }

  const candidates = [];
  const seenFeatures = new Set();
  map.forEachFeatureAtPixel(event.pixel, function (feature, layer) {
    if (layer && layer.get('layer_name') && !seenFeatures.has(feature)) {
      seenFeatures.add(feature);
      candidates.push({ feature, layer });
    }
  }, {
    hitTolerance: 5,
    layerFilter: function (layer) {
      return Boolean(layer && layer.getVisible() && layer.get('layer_name'));
    },
  });

  candidates.sort(function (left, right) {
    return (right.layer.getZIndex() || 0) - (left.layer.getZIndex() || 0);
  });

  if (candidates.length === 0) {
    hideObjectCandidates();
    select.getFeatures().clear();
    objInfo.style.display = 'none';
    return;
  }

  if (candidates.length === 1) {
    selectObjectCandidate(candidates[0].feature, candidates[0].layer);
    return;
  }

  select.getFeatures().clear();
  showObjectCandidates(candidates);
});

function makeFields(f, sourceCoordinate, objGeomType, selectedLayer) {
  // подбор полей для отрисовки
  const layerName = selectedLayer.get('layer_name');
  let t_str = ``;
  let fields = [];
  for (let i in f['values_']) {
    if (!isTechnicalField(i)) {
      fields.push(i)
      const fieldTitle = prjLayersInfo[layerName]['fields'][i] || i;
      t_str += `<label class="info_labels">${escapeHtml(fieldTitle)}:</label><br>
            <input type="text" id="select_${escapeHtml(i)}" value="${escapeHtml(f['values_'][i])}" size="32" disabled>
            <br>`;
    }
  }
  objInfo.style.display = 'inline';
  objInfoDiv.innerHTML = t_str;
  modifyBtn.disabled = false;
  cancelMdfBtn.disabled = false;
  snapMdfBtn.disabled = true;
  deleteMdfBtn.disabled = true;
  // Обработчики кнопок в блоке object_info
  modifyBtn.onclick = () => modifyObject(f, sourceCoordinate, objGeomType)
  cancelMdfBtn.onclick = () => cancelModify(f, sourceCoordinate)
  saveMdfBtn.onclick = () => saveModify(f, fields, selectedLayer, 'modify', sourceCoordinate)
  deleteMdfBtn.onclick = () => saveModify(f, fields, selectedLayer, 'delete', sourceCoordinate)
  const snap = new Snap({ source: selectedLayer.getSource() });
  snapMdfBtn.onclick = () => snapModeSwitch(snap)
}
