// Тултипы при наведении на объекты
// https://openlayers.org/en/latest/examples/tooltip-on-hover.html
const info_tp = document.getElementById('info_tooltip');
const displayFeatureInfo = function (pixel, target) {
  const hit = target.closest?.('.ol-control')
    ? undefined
    : map.forEachFeatureAtPixel(pixel, function (feature, layer) {
      if (layer && layer.get('layer_name')) {
        return { feature, layer };
      }
      return undefined;
    }, {
      hitTolerance: 3,
      layerFilter: function (layer) {
        return Boolean(layer && layer.getVisible() && layer.get('layer_name'));
      },
    });
  if (hit) {
    info_tp.style.left = pixel[0] + 'px';
    info_tp.style.top = pixel[1] + 'px';
    const idValue = hit.feature.get('id');
    const nameValue = hit.feature.get('name');
    const idLabel = idValue === undefined || idValue === null
      ? ''
      : String(idValue).trim();
    const nameLabel = nameValue === undefined || nameValue === null
      ? ''
      : String(nameValue).trim();

    if (idLabel || nameLabel) {
      const tooltipLines = [];
      if (idLabel) {
        tooltipLines.push(`ID: ${idLabel.slice(0, 15)}`);
      }
      if (nameLabel) {
        tooltipLines.push(nameLabel.slice(0, 24));
      }
      info_tp.innerText = tooltipLines.join('\n');
      info_tp.style.visibility = 'visible';
    } else {
      info_tp.innerText = '';
      info_tp.style.visibility = 'hidden';
    }
  } else {
    info_tp.innerText = '';
    info_tp.style.visibility = 'hidden';
  }
};

map.on('pointermove', function (evt) {
  if (evt.dragging) {
    info_tp.style.visibility = 'hidden';
    return;
  }
  const pixel = map.getEventPixel(evt.originalEvent);
  displayFeatureInfo(pixel, evt.originalEvent.target);
});

map.getTargetElement().addEventListener('pointerleave', function () {
  info_tp.style.visibility = 'hidden';
});


/////// Измерения длины и площади //////
const typeMeasureSelect = document.getElementById('measure_type');
let modifyMeasure = null;
const segmentStyles = [segmentStyleMsr];

const formatLength = function (line) {
  const length = getLength(line);
  let output;
  if (length > 100) {
    output = Math.round((length / 1000) * 100) / 100 + ' км';
  } else {
    output = Math.round(length * 100) / 100 + ' м';
  }
  return output;
};

const formatArea = function (polygon) {
  const area = getArea(polygon);
  let output;
  if (area > 10000) {
    output = Math.round((area / 1000000) * 100) / 100 + ' км\xB2';
  } else {
    output = Math.round(area * 100) / 100 + ' м\xB2';
  }
  return output;
};
let tipPoint;

function styleFunction(feature, segments, drawType, tip) {
  const styles = [];
  const geometry = feature.getGeometry();
  const type = geometry.getType();
  let point, label, line;
  if (!drawType || drawType === type || type === 'Point') {
    styles.push(styleMsr);
    if (type === 'Polygon') {
      point = geometry.getInteriorPoint();
      label = formatArea(geometry);
      line = new LineString(geometry.getCoordinates()[0]);
    } else if (type === 'LineString') {
      point = new Point(geometry.getLastCoordinate());
      label = formatLength(geometry);
      line = geometry;
    }
  }
  if (segments && line) {
    let count = 0;
    line.forEachSegment(function (a, b) {
      const segment = new LineString([a, b]);
      const label = formatLength(segment);
      if (segmentStyles.length - 1 < count) {
        segmentStyles.push(segmentStyleMsr.clone());
      }
      const segmentPoint = new Point(segment.getCoordinateAt(0.5));
      segmentStyles[count].setGeometry(segmentPoint);
      segmentStyles[count].getText().setText(label);
      styles.push(segmentStyles[count]);
      count++;
    });
  }
  if (label) {
    labelStyleMsr.setGeometry(point);
    labelStyleMsr.getText().setText(label);
    styles.push(labelStyleMsr);
  }
  if (
    tip &&
    type === 'Point' &&
    !modifyMeasure.getOverlay().getSource().getFeatures().length
  ) {
    tipPoint = geometry;
    tipStyleMsr.getText().setText(tip);
    styles.push(tipStyleMsr);
  }
  return styles;
}

function addMeasureInteraction() {
  const drawType = typeMeasureSelect.value;
  modifyMeasure = new Modify({ source: measureSource, style: modifyStyleMsr });
  const activeTip =
    'Кликните для продолжения измерений ' +
    (drawType === 'Polygon' ? 'площади' : 'линии');
  const idleTip = 'Начало измерений - одинарный клик мыши,\n завершение - двойной';
  let tip = idleTip;
  drawMeasure = new Draw({
    source: measureSource,
    type: drawType,
    style: function (feature) {
      return styleFunction(feature, false, drawType, tip); // false, чтоб убрать длину сегментов
    },
  });
  drawMeasure.on('drawstart', function () {
    // if (clearPrevious.checked) {
    measureSource.clear();
    // }
    modifyMeasure.setActive(false);
    tip = activeTip;
  });
  drawMeasure.on('drawend', function () {
    modifyStyleMsr.setGeometry(tipPoint);
    modifyMeasure.setActive(true);
    map.once('pointermove', function () {
      modifyStyleMsr.setGeometry();
    });
    tip = idleTip;
  });
  modifyMeasure.setActive(true);
  map.addInteraction(drawMeasure);
}

typeMeasureSelect.onchange = function () {
  map.removeInteraction(drawMeasure);
  addMeasureInteraction();
};
